  "Mit einem kostenlosen API-Key zeigt das Dashboard deine Hüter (Lichtlevel, Klasse, zuletzt gespielt). Die Daten kommen direkt von Bungie – ohne Anmeldung im Tool. Es werden nur öffentliche Profildaten gelesen.": "With a free API key, the dashboard shows your Guardians (light level, class, last played). The data comes directly from Bungie - without registering in the tool. Only public profile data is read.",
