  "ein.": "a.",
  "Bungie-Anmeldung (OAuth, Stufe 1)": "Bungie Login (OAuth, Level 1)",
  "Mit der Anmeldung nutzt das Tool deinen Hüter **auch dann**, wenn das Profil privat ist – und legt die Basis für Inventar/Loadouts (Stufe 2). Die Tokens bleiben auf diesem PC.": "When you register, the tool uses your Guardian **even** if the profile is private - and sets the basis for inventory/loadouts (level 2). The tokens remain on this PC.",
