  "Hier siehst du Prioritäten, Reset und Xûr. „Mehr anzeigen“ öffnet Wochen-, Sammlungs- und Statuskarten.": "Here you can see Priorities, Reset and Xûr. “Show more” opens weekly, collection and status cards.",
  "Suche, Filter und Kartenansicht. Rechtsklick auf ein Item öffnet direkt die Details.": "Search, filter and map view. Right-clicking on an item opens the details directly.",
  "Werkzeuge": "Tools",
  "Builds, Sammlung, Woche und Händler. Die Bereiche sind bewusst aufklappbar, damit nichts überladen wirkt.": "Builds, Collection, Week and Dealer. The areas are deliberately foldable so that nothing appears overloaded.",
  "Strg+K öffnet die Befehlspalette. Strg+Alt+1–5 springt direkt in die Werkzeuge-Ansichten.": "Ctrl+K opens the command palette. Ctrl+Alt+1–5 jumps directly to the tools views.",
  "Anpassen": "Customize",
  "Unter Einstellungen kannst du einfache Ansicht, Schriftgröße, Startansicht und Benachrichtigungen ändern.": "In Settings you can change the basic view, font size, home view and notifications.",
