  "Einsammeln fehlgeschlagen": "Collection failed",
  "Schnittstelle nicht verfügbar.": "Interface not available.",
  "Beschwörer": "Warlock",
  "Xûr-Daten werden geladen …": "Loading Xûr data...",
  "Warlock": "Warlock",
  "Kleines, dauerhaft sichtbares Fenster mit der Anzahl der Gegenstände in der Poststelle (Kapazität 21). Gelb ab 15, rot ab 19 – so siehst du rechtzeitig, wann es zum Turm geht. Das Fenster lässt sich frei verschieben; die Position wird gespeichert.": "Small, permanently visible window showing the number of items in the mailroom (capacity 21). Yellow from 15, red from 19 - so you can see in good time when it's time to go to the tower. The window can be moved freely; the position is saved.",
  "DIM betreibt eine eigene, zentral registrierte Bungie-Anwendung mit eigenem API-Key und OAuth-Client. Diese Zugangsdaten gehören DIM, werden nicht veröffentlicht und dürfen nicht in anderen Tools wiederverwendet werden. Deshalb braucht dieses Tool eine eigene kostenlose Bungie-Anwendung: API-Key + OAuth-Client-ID, das Client-Secret nur für dauerhaftes Angemeldetbleiben.": "DIM operates its own, centrally registered Bungie application with its own API key and OAuth client. These credentials belong to DIM, will not be published and may not be reused in other tools. That's why this tool needs its own free Bungie application: API key + OAuth client ID, the client secret only for staying logged in permanently.",
  "Dieses Tool ist ein inoffizielles Community-Projekt und steht in keiner Verbindung zu Bungie. Destiny 2 und alle zugehörigen Inhalte sind Eigentum von Bungie, Inc. Die verlinkten Webseiten gehören ihren jeweiligen Betreibern.": "This tool is an unofficial community project and is not affiliated with Bungie. Destiny 2 and all related content are the property of Bungie, Inc. The linked websites belong to their respective operators.",
  "Raid-Callouts, Mechaniken, Schadensphasen... # Überschrift - Liste **fett** *kursiv*": "Raid callouts, mechanics, damage phases... # Heading - List **bold** *italics*",
