  "Keine OAuth-Client-ID gesetzt (Einstellungen → Bungie).": "No OAuth client ID set (Settings → Bungie).",
  "Bungie-Anmeldung": "Bungie login",
  "Bungie hat keinen Refresh-Token ausgestellt (App ist „öffentlich“): Nach ca. 1 Stunde ist eine neue Anmeldung nötig. Dauerhaft angemeldet bleiben: Einstellungen → Bungie → „Vertrauliche App“ + Client-Secret.": "Bungie has not issued a refresh token (app is “public”): A new login is required after about 1 hour. Stay logged in permanently: Settings → Bungie → “Confidential App” + Client Secret.",
  "API-Key zuerst setzen (nötig für den Token-Tausch).": "Set API key first (necessary for token exchange).",
  "Bungie-Token-Tausch fehlgeschlagen": "Bungie token swap failed",
  "– bitte API-Key, Client-ID und Origin im Bungie-Portal prüfen. Wichtig: Das Client-Secret darf nur eingetragen sein, wenn die App im Portal auf „Vertraulich“ steht (öffentliche Apps dürfen kein Secret senden). Danach in 1–2 Minuten erneut versuchen.": "– please check API key, client ID and origin in the Bungie portal. Important: The client secret may only be entered if the app is set to “Confidential” in the portal (public apps are not allowed to send a secret). Then try again in 1-2 minutes.",
  "Bungie-Login erfolgreich": "Bungie login successful",
  "Bungie stellt keinen Refresh-Token aus (Public Client)": "Bungie does not issue a refresh token (Public Client)",
  "Kein Refresh-Token vorhanden – die Bungie-App ist vermutlich als „Öffentlicher Client“ registriert. Bungie stellt dann keinen Refresh-Token aus, deshalb ist nach ca. 1 Stunde eine neue Anmeldung nötig. Abhilfe: im Bungie-Portal „Vertraulich“ wählen, das Client-Secret hier eintragen und einmal neu anmelden.": "No refresh token present - the Bungie app is probably registered as a “public client”. Bungie will not issue a refresh token, so you will need to log in again after about 1 hour. Remedy: select “Confidential” in the Bungie portal, enter the client secret here and log in again.",
  "Bungie-Anmeldung unvollständig (API-Key/Client-ID fehlen).": "Bungie login incomplete (API key/client ID missing).",
  "Bungie-Token-Erneuerung fehlgeschlagen": "Bungie token renewal failed",
  "Bungie-Token erneuert": "Bungie token renewed",
  "Anmeldung abgelaufen – Bungie stellt für „öffentliche“ Apps keinen Refresh-Token aus. Bitte neu anmelden (oder App auf „Vertraulich“ + Client-Secret umstellen).": "Registration expired - Bungie does not issue a refresh token for “public” apps. Please log in again (or change the app to “Confidential” + Client Secret).",
