  "6-Spieler-Endgame. Zwei Raids sind pro Woche featured und dann komplett farmbar. Encounter lassen sich wiederholen; der Endvendor verkauft gezielte Red-Border-Waffen für Spoils of Conquest. Master-Challenges geben Adept-Waffen.": "6 player endgame. Two raids are featured per week and are then completely farmable. Encounters can be repeated; the end vendor sells targeted Red Border weapons for Spoils of Conquest. Master Challenges give Adept weapons.",
  "Feuerteam 6": "Fire Team 6",
  "Featured-Rotation": "Featured rotation",
  "Featured-Raid wählen, Ziel-Encounter farmen und 20 Spoils für einen gezielten Red-Border beim Endvendor sparen.": "Choose a featured raid, farm target encounters and save 20 spoils for a targeted red border with the end vendor.",
  "3-Spieler-Endgame. Zwei Dungeons sind pro Woche featured und farmbar. Die Exotic-Waffe droppt meist beim Endboss; Checkpoints erlauben einzelne Bosse.": "3 player endgame. Two dungeons are featured and farmable per week. The exotic weapon usually drops from the final boss; Checkpoints allow individual bosses.",
  "Feuerteam 3": "Fire team 3",
  "Boss-Checkpoint suchen, gewünschten Encounter wiederholen und in der Featured-Woche auf Tier-5-Beute spielen.": "Find the boss checkpoint, repeat the desired encounter and play for tier 5 loot in the featured week.",
  "Saisonale Aktivitäten, Vendor-Fokussierung und Engramme. Red-Border-Waffen kommen aus Saisonaktivitäten, dem Saisonvendor und fokussierten Engrammen; ältere Saisons rotieren über Legacy-Quellen.": "Seasonal activities, vendor focus and engrams. Red Border weapons come from seasonal activities, the seasonal vendor, and focused engrams; older seasons rotate via legacy sources.",
  "Saisonvendor": "Seasonal vendor",
  "Fokussierung": "Focusing",
  "Saisonvendor und fokussierte Engramme nutzen; Red-Border-Waffen zuerst für offene Baupläne ausgeben.": "Use seasonal vendors and focused engrams; Spend Red Border weapons on open blueprints first.",
  "Wöchentlich rotierende Nightfall-Waffe. Höhere Schwierigkeiten und Grandmaster verbessern die Chancen; Vanguard-Rangaufstiege geben zusätzliche Engramme.": "Weekly rotating Nightfall weapon. Higher difficulties and Grandmaster improve the odds; Vanguard rank ups give additional engrams.",
  "Wöchentliche Nightfall-Waffe prüfen und für die beste Chance Grandmaster mit Champion-Abdeckung spielen.": "Check Weekly Nightfall Weapon and play Grandmaster with Champion Coverage for the best chance.",
  "Woche-langes Crucible-Event bei Saladin. Rangaufstiege, tägliche Challenges und fokussierte Engramme; Eisenbanner-Ausrüstung zählt für Sets.": "Week-long Crucible event at Saladin. Rank Advancements, Daily Challenges and Focused Engrams; Iron Banner equipment counts for sets.",
  "Crucible-Event": "Crucible event",
  "Tägliche Challenges mitnehmen, Rang aufbauen und Engramme auf die gewünschte Waffe fokussieren.": "Take daily challenges, build rank and focus engrams on the desired weapon.",
  "Prüfungen": "Exams",
  "Wochenend-PvP bei Saint-14. Passagen, Siege und Flawless belohnen mit Trials-Engrammen, fokussierten Waffen und Lighthouse-Loot.": "Weekend PvP at Saint-14. Passages, Siege and Flawless reward with Trials engrams, focused weapons and Lighthouse loot.",
  "Wochenende": "weekend",
  "Passage wählen, Siege sammeln und Engramme nach dem Wochenend-Run beim Händler fokussieren.": "Choose a passage, collect victories and focus engrams at the dealer after the weekend run.",
  "PvP-Playlists mit wöchentlichen Challenges und Rangaufstiegen bei Shaxx. Eisenbanner und Prüfungen haben eigene Rotations- und Fokus-Belohnungen.": "PvP playlists with weekly challenges and rank advancements at Shaxx. Iron Banners and Trials have their own rotation and focus rewards.",
  "Rangaufstieg": "Rank advancement",
  "Wöchentliche Crucible-Challenges abschließen und Rangaufstiegs-Engramme beim Händler öffnen.": "Complete weekly Crucible challenges and open rank-up engrams from the merchant.",
  "PvE/PvP-Modus beim Drifter. Rangaufstiege, wöchentliche Challenges und fokussierte Engramme.": "PvE/PvP mode at Drifter. Rank advancements, weekly challenges and focused engrams.",
  "Drifter": "Drifters",
  "Wöchentliche Gambit-Challenges spielen und Rangaufstiegs-Engramme gezielt fokussieren.": "Play weekly Gambit challenges and focus on rank-up engrams.",
  "Wöchentlich rotierender Spielshow-Modus. Truhe am Ende, wechselnde Waffen und Sternenstaub; gute Quelle für ältere Ausrüstung.": "Weekly rotating game show mode. Chest at the end, changing weapons and stardust; good source for older gear.",
  "Truhe": "chest",
  "Legacy-Loot": "Legacy loot",
  "Wöchentliche Rotation prüfen und die Truhe am Ende für wechselnde Waffen und Materialien öffnen.": "Check weekly rotation and open the chest at the end for rotating weapons and materials.",
  "Exotic-Mission": "Exotic mission",
  "Wöchentlich rotierende Exotic-Mission. Seltene Waffen, Katalysatoren und Patterns; pro Woche gibt es oft eine garantierte Belohnung.": "Weekly rotating Exotic mission. Rare Weapons, Catalysts and Patterns; There is often a guaranteed reward per week.",
  "Katalysator": "Catalyst",
  "Wöchentliche Mission einmal pro Charakter spielen und die garantierte Waffe bzw. den Katalysator mitnehmen.": "Play the weekly mission once per character and take the guaranteed weapon or catalyst with you.",
  "Patrouillen, öffentliche Events, verlorene Sektoren und Ziele auf den Destinationen. Wöchentliche Powerful-/Pinnacle-Quellen; gut für Einstiegsausrüstung.": "Patrols, public events, lost sectors and targets on the destinations. Powerful/Pinnacle Weekly Sources; good for entry level equipment.",
  "Open World": "Open world",
  "Wöchentliche Destination-Ziele und verlorene Sektoren abhaken; öffentliche Events für schnelle Beute mitnehmen.": "Check off weekly destination goals and lost sectors; public events for quick loot.",
  "Händler wie Banshee-44, Xûr, Rahool und Saisonvendoren. Fokussierung, Rangaufstiege und wöchentliche Rotationen.": "Vendors like Banshee-44, Xûr, Rahool and Saisonvendoren. Focus, rank advancements and weekly rotations.",
  "Engramme": "Engrams",
  "Wöchentliches Händlerangebot prüfen, Engramme fokussieren und Rangaufstiegspakete gezielt öffnen.": "Check weekly dealer offers, focus engrams and open rank advancement packages specifically.",
  "Enklave und Relikt: Baupläne extrahieren, Waffen formen und mit verbesserten Perks aufwerten.": "Enclave and Relic: Extract blueprints, shape weapons and upgrade them with improved perks.",
