  "Punkte sind eine Orientierung: Rüstung, Energie, Mods, Stats, Meisterwerk, Artefakt, Set-Bonus.": "Points are a guide: Armor, Energy, Mods, Stats, Masterpiece, Artifact, Set Bonus.",
  "\" title=\"Build-Gesundheit\">❤": "\" title=\"Build Health\">❤",
