  "Energie-Upgrades (Kapazität → 10)": "Energy Upgrades (Capacity → 10)",
  "PvE / Allgemein": "PvE / General",
  "Gesundheit und Klasse für Überleben und Fähigkeiten.": "Health and class for survival and skills.",
  "PvP / Schmelztiegel": "PvP / Crucible",
  "Waffen und Gesundheit für Duellanten.": "Weapons and health for duelists.",
  "Gesundheit und Super; Exoten aus, damit der Slot frei bleibt.": "health and super; Exotics so that the slot remains free.",
  "Granate und Super für Burst-Schaden.": "Grenade and Super for burst damage.",
  "Ausgeglichen für Solo- und Gruppenläufe.": "Balanced for solo and group runs.",
  "Build-Assistent": "Build Wizard",
  "Der Assistent setzt Ziele, Meisterwerk und Exoten-Regel und startet den Picker. Danach kannst du feinjustieren.": "The assistant sets goals, masterpiece and exotic rule and starts the picker. Then you can fine-tune.",
  "Picker starten": "Start picker",
  "Ziele gesetzt – Picker rechnet …": "Goals set – Picker calculates...",
  "Hilfe & Erklärungen": "Help & explanations",
  "Bild-Cache leeren": "Clear image cache",
  "Noch": "Still",
  "Benachrichtigung, wenn eine Waffe mit allen genannten Perks im Inventar auftaucht.": "Notification when a weapon with all of the mentioned perks appears in the inventory.",
  "Sonntag": "Sunday",
  "Montag": "Monday",
  "Dienstag": "Tuesday",
  "Mittwoch": "Wednesday",
  "Donnerstag": "Thursday",
  "Freitag": "Friday",
  "Samstag": "Saturday",
  "Zeitplan speichern": "Save schedule",
  "Sendet über den Webhook aus den Einstellungen. Der Zeitplan läuft im Hintergrund (einmal pro Tag).": "Sends via webhook from settings. The schedule runs in the background (once per day).",
  "Basiswerte + Stat-Mods (+10 je Mod) + Meisterwerk (+10) + Fragmente/Subklasse + Tuning (+5) + Artifice (+3). Maximal 200 je Stat. Exoten: erlaubt (max. 1), verboten oder nur mit Exot.": "Base Stats + Stat Mods (+10 per mod) + Masterwork (+10) + Fragments/Subclass + Tuning (+5) + Artifice (+3). Maximum 200 per stat. Exotics: allowed (max. 1), forbidden or only with exotics.",
  "Energie & Mods": "Energy & Mods",
  "Jedes Rüstungsteil hat drei allgemeine Mod-Plätze. Stat-Mods kosten 3 Energie. „Energie ausgleichen\" verteilt Mods auf freie Plätze innerhalb der Kapazität.": "Each piece of armor has three general mod slots. Stat mods cost 3 energy. \"Balance Energy\" distributes mods to free slots within the capacity.",
  "Artefakt-Perks werden beim Anwenden über den Artefakt-Socket gesteckt. Nicht freigeschaltete Perks lehnt Bungie ab und werden im Ergebnis genannt.": "Artifact perks are plugged into the artifact socket when applied. Bungie rejects perks that have not been unlocked and will be mentioned in the result.",
  "DIM-Import": "DIM import",
  "dim.gg-Links oder URLs mit ?loadout=… einfügen. Der Import zeigt Items, Mods und unbekannte Einträge vor dem Speichern.": "Insert dim.gg links or URLs with ?loadout=…. The import shows items, mods and unknown entries before saving.",
  "Reset dienstags 18:00 (17:00 UTC). Eigene Punkte können täglich/wöchentlich zurückgesetzt werden. „Offene übernehmen\" kopiert unerledigte Punkte.": "Reset Tuesdays 6:00 p.m. (5:00 p.m. UTC). Your points can be reset daily/weekly. \"Take Open\" copies unfinished items.",
  "Quellen & Sammlung": "Sources & Collection",
  "Quellen zeigen Besitzquote, Red-Border-Fortschritt und Farmrouten. Ziele lassen sich als Wochenaufgabe oder Sammlungs-Ziel übernehmen.": "Sources show ownership rates, Red Border progress and farm routes. Goals can be adopted as weekly tasks or collection goals.",
  "Godroll-Score": "Godroll score",
  "Treffer zählen mit Gewicht, fehlende Perks mit reduziertem Gewicht, Meisterwerk als Bonus. Der Score wird auf 100 normiert; Perk-Gewichte sind einstellbar.": "Hits count with weight, missing perks count with reduced weight, masterwork counts as a bonus. The score is normalized to 100; Perk weights are adjustable.",
  "Strg+K öffnet die Palette, / fokussiert die Suche, ? zeigt Kürzel. LB/RB wechseln Bereiche, B schließt Dialoge, Pfeiltasten navigieren Kacheln.": "Ctrl+K opens the palette / focuses the search, ? shows abbreviations. LB/RB switch areas, B closes dialogs, arrow keys navigate tiles.",
  "Fehlermeldungen": "Error messages",
  "„Nicht angemeldet/abgelaufen\": Zugangsdaten-Karte prüfen. „429\": Bungie drosselt, Queue abwarten. „Energie reicht nicht\": Checkliste oder Energie ausgleichen.": "\"Not logged in/expired\": Check access data card. \"429\": Bungie throttles, wait for the queue. “Energy is not enough”: checklist or balance energy.",
  "Hilfe durchsuchen …": "Browse Help...",
  "Bild-Cache leeren? Bungie-Icons werden beim nächsten Anzeigen neu geladen.": "Clear image cache? Bungie icons will reload the next time they are viewed.",
