  "Für Spieler auf dem Sofa. Vergrößert alles, blendet Kleinstinfos aus und hält Details per Fokus/Controller erreichbar. Standardmäßig aus.": "For players on the sofa. Enlarges everything, hides small information and keeps details accessible via focus/controller. Off by default.",
