  "Steam Input & Fokus": "Steam input & focus",
  "Steam Input kann den Controller im Overlay auf Tastatur/Maus umschalten. So bekommt Destiny 2 keine Gamepad-Eingaben, während das Overlay fokussiert ist. Das Tool bleibt dabei vollständig extern – es wird nichts in das Spiel injiziert.": "Steam Input can switch the controller to keyboard/mouse in the overlay. So Destiny 2 doesn't get any gamepad input while the overlay is focused. The tool remains completely external - nothing is injected into the game.",
