  "„Dauerhaft“ holt den Fokus zurück, wenn das Overlay ihn verliert. „Nur beim Öffnen“ schützt die ersten 10 Sekunden.": "Permanent regains focus when the overlay loses it. “Only when opened” protects the first 10 seconds.",
